{
  "implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        gain = call['loss_without_call'] - call['loss_with_call']
        norm_gain = round(gain / call['prediction_tokens'], 8)
        is_accepted = call['parseable'] and norm_gain >= threshold
        diagnostics.append({
            'accepted': is_accepted,
            'call_id': call['call_id'],
            'normalized_gain': norm_gain
        })
        if is_accepted:
            accepted_call_ids.append(call['call_id'])
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"
}
